<script setup>
import ChantierPresence from './ChantierPresence.vue';
import {needsSaveBeforeCopy,sameRevision} from './chantier-state.js';
import {inheritTypeExtras} from './type-extras.js';
import { quotationSelection } from "./quantity.js";
import {printDocument} from "./printing.js";
import {ref, computed, watch, onBeforeUnmount} from 'vue';
import {showSectionGenerator} from './section-generator.js';
import ChantierAutocomplete from './ChantierAutocomplete.vue';
import FrappeCell from './FrappeCell.vue';
import { assignmentIds } from './chantier-selection.js';
import CommercialExtrasPanel from './CommercialExtrasPanel.vue';
const frappe = window.frappe;
const api='mat_reco.material_reconfiguration.services.chantier_service.';
const data=ref({chantiers:[],sections:[],quotations:[],sales_orders:[],lines:[],summary:{}}), selected=ref(''), section=ref(''), busy=ref(false), error=ref('');
const dirty=ref(false), chosen=ref({}), quoteKey=ref(null),assignmentTargets=ref([]),expandedArticles=ref({});
const extrasCatalogue=ref([]),pageActive=ref(false),stale=ref(false);
function markDirty(){if(commercialDraft.value)dirty.value=true;}
function onDocumentUpdate(event){if(!sameRevision(event.modified,data.value.chantier?.modified))stale.value=true;}
function reloadDossier(){if(busy.value)return;const reload=()=>{closeExtras();refresh();};if(dirty.value&&commercialDraft.value)frappe.confirm('Actualiser et abandonner les modifications non enregistrées ?',reload);else reload();}
const sectionsOpen=ref(true),drawerTargets=ref([]),drawerTypeId=ref(''),typeFilter=ref('');
const sectionTarget=ref('');
const sectionRow=computed(()=>(data.value.chantier?.lines||[]).find(row=>row.line_id===sectionTarget.value));
function pickSection(row){sectionTarget.value=sectionTarget.value===row.line_id?'':row.line_id;sectionsOpen.value=true;}
function assignSection(value){if(!commercialDraft.value||busy.value||!sectionRow.value||!(value===''||data.value.sections.some(s=>s.name===value)))return;sectionRow.value.section=value;dirty.value=true;}
function openExtras(row){drawerTypeId.value='';sectionTarget.value='';drawerTargets.value=assignmentIds(assignmentTargets.value,row.line_id);}
const lineAmount=row=>Number(row.qty||0)*Number(row.rate||0)*(row.price_per_sqm?Number(row.length_mm||0)*Number(row.width_mm||0)/1e6:1)*(1-(data.value.chantier?.discount_mode==='Montant'?0:Number(row.discount_percentage||0))/100);
const total=computed(()=>{const c=data.value.chantier;return [...(c?.lines||[]),...(c?.commercial_extras||[])].reduce((n,r)=>n+lineAmount(r),0)-(c?.discount_mode==='Montant'?Number(c.discount_value||0):0);});
function applyDefaultDiscounts(){const c=data.value.chantier;if(!c||!commercialDraft.value)return;for(const row of [...c.lines,...(c.commercial_extras||[])]){if(c.discount_mode==='Montant')row.discount_percentage=0;else if(!row.discount_override)row.discount_percentage=Number(c.discount_value||0);}}
watch(()=>[data.value.chantier?.discount_mode,data.value.chantier?.discount_value,(data.value.chantier?.lines||[]).map(r=>r.line_id).join(','),(data.value.chantier?.commercial_extras||[]).map(r=>r.line_id).join(',')],applyDefaultDiscounts);
function setLineDiscount(row){row.discount_override=1;dirty.value=true;}

function toggleAllTargets(){const visible=macroLines.value.map(l=>l.line_id);assignmentTargets.value=visible.every(id=>assignmentTargets.value.includes(id))?assignmentTargets.value.filter(id=>!visible.includes(id)):[...new Set([...assignmentTargets.value,...visible])];}
function applyExtras(rows){if(!rows.length)return;data.value.chantier.commercial_extras||=[];data.value.chantier.commercial_extras.push(...rows);dirty.value=true;}
function updateLineExtra({line_id,field,value}){
 const extra=data.value.chantier.commercial_extras.find(r=>r.line_id===line_id);
 if(!commercialDraft.value||!extra||!['qty','rate','discount_percentage'].includes(field)||!Number.isFinite(Number(value)))return;
 extra[field]=Number(value);if(field==='discount_percentage'){extra.discount_override=1;}else if(field==='qty'){extra.manual_qty=1;if(extra.inherited_from)extra.inherited_qty_override=1;}else{extra.rate_set=1;if(extra.inherited_from)extra.inherited_rate_override=1;}dirty.value=true;
}
async function beforeBatch(){return !dirty.value||await saveMacro();}
const technicalApi='mat_reco.material_reconfiguration.services.technical_study_service.';
let serial=0, timer=null;
async function call(method,args={}) { return (await frappe.call({method:api+method,args,type:method==='get_dossier'?'GET':'POST'})).message; }
function describe(e) { try{return JSON.parse(JSON.parse(e._server_messages)[0]).message;}catch{return e.message||'Impossible de charger le dossier.';} }
async function refresh() {
 const request=++serial; busy.value=true;error.value='';
 try {const [result,catalogue]=await Promise.all([call('get_dossier',{chantier:selected.value||null}),frappe.call({method:'mat_reco.material_reconfiguration.services.chantier_extras.catalogue',type:'GET'}).then(r=>r.message||[]).catch(()=>[])]);extrasCatalogue.value=Array.isArray(catalogue)?catalogue:[];if(request===serial){if(result.chantier)result.chantier.discount_mode||='Pourcentage';data.value=result;dirty.value=false;stale.value=false;chosen.value=quotationSelection(result.chantier?.lines||[],result.quote_usage);}}
 catch(e){if(request===serial)error.value=describe(e);} finally{if(request===serial)busy.value=false;}
}
function choose(){drawerTypeId.value='';sectionTarget.value='';section.value='';assignmentTargets.value=[];drawerTargets.value=[];refresh();}
const scope=computed(()=>{const names=new Set(section.value?[section.value]:[]);let changed=true;while(changed){changed=false;for(const s of data.value.sections)if(names.has(s.parent_chantier_section)&&!names.has(s.name)){names.add(s.name);changed=true;}}return names;});
const macroLines=computed(()=>(data.value.chantier?.lines||[]).filter(l=>(!section.value||scope.value.has(l.section))&&(!loose.value||!typeFilter.value||(typeFilter.value==='__direct__'?l.line_kind==='Vente directe':l.work_type===typeFilter.value))));
const commercialOpen=computed(()=>data.value.chantier?.docstatus===0&&data.value.chantier?.status!=='Cancelled'&&data.value.permissions?.write);
const commercialDraft=computed(()=>commercialOpen.value&&!data.value.permissions?.ft_locked);
const ftActive=computed(()=>!!data.value.chantier?.ft_active&&!dirty.value);
const loose=computed(()=>Number(data.value.chantier?.workflow_version||0)>=2);
const workTypes=computed(()=>data.value.chantier?.work_types||[]);
const hasManufacturing=computed(()=>(data.value.chantier?.lines||[]).some(r=>r.line_kind!=='Vente directe'));
function inheritDraftExtras(){if(commercialDraft.value&&loose.value)inheritTypeExtras(data.value.chantier,extrasCatalogue.value);}
watch(()=>[busy.value,JSON.stringify((data.value.chantier?.lines||[]).map(r=>[r.line_id,r.work_type,r.line_kind,r.qty,r.length_mm,r.width_mm])),JSON.stringify(workTypes.value.map(t=>[t.type_id,t.common_extras]))],()=>{if(!busy.value)inheritDraftExtras();});
const drawerWorkType=computed(()=>workTypes.value.find(t=>t.type_id===drawerTypeId.value));
function openTypeExtras(type){drawerTargets.value=[];drawerTypeId.value=type.type_id;}
function closeExtras(){drawerTargets.value=[];drawerTypeId.value='';}
function applyTypeExtras(extras){if(!drawerWorkType.value)return;drawerWorkType.value.common_extras=JSON.stringify(extras);inheritDraftExtras();dirty.value=true;}
watch(()=>workTypes.value.map(t=>t.type_id),ids=>{if(typeFilter.value&&typeFilter.value!=='__direct__'&&!ids.includes(typeFilter.value))typeFilter.value=ids[0]||'';},{immediate:true});
const readyForQuote=computed(()=>data.value.chantier?.docstatus===1&&(loose.value||data.value.technical?.docstatus===1&&!data.value.technical_stale));
const techLine=(id)=>data.value.technical?.lines?.find(l=>l.line_id===(loose.value?data.value.chantier.lines.find(r=>r.line_id===id)?.work_type:id));
const effectiveUom=(row)=>row.uom||JSON.parse(techLine(row.line_id)?.tree_json||'{}').stock_uom||'Unité à définir';
const lines=computed(()=>data.value.lines.filter(l=>!section.value||scope.value.has(l.section)));
const summary=computed(()=>section.value?(data.value.by_section?.[section.value]||{}):data.value.summary);
const depth=(node)=>{let n=0,seen=new Set();while(node?.parent_chantier_section&&!seen.has(node.name)){seen.add(node.name);n++;node=data.value.sections.find(s=>s.name===node.parent_chantier_section);}return n;};
const stateName=(value)=>({completed:'Terminée',ready:'Réalisable',partial:'Partiellement réalisable',blocked:'Bloquée',ok:'Besoin satisfait',Preparation:'Préparation',Quotation:'Chiffrage',Confirmed:'Confirmé','In Production':'En fabrication',Completed:'Terminé','On Hold':'Suspendu',Draft:'Brouillon','To Deliver and Bill':'À livrer et facturer','To Deliver':'À livrer','To Bill':'À facturer',Closed:'Clôturée',Cancelled:'Annulé'})[value]||value;
const sectionName=(name)=>data.value.sections.find(s=>s.name===name)?.section_name||'Sans section';
const fmt=(n)=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
function open(dt,name){frappe.set_route('Form',dt,name);}
function form(title,fields,onSave,reload=true) {const dialog=new frappe.ui.Dialog({title,fields,primary_action_label:'Enregistrer',async primary_action(values){dialog.disable_primary_action();try{await onSave(values);dialog.hide();if(reload)await refresh();}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();return dialog;}
function newChantier(){let dialog;dialog=form('Nouveau chantier',[
 {fieldname:'reference',label:'Référence',fieldtype:'Data',read_only:1,description:'Numéro automatique attribué à l’enregistrement (YYCHANTMM#####).'},{fieldname:'designation',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'company',label:'Société',fieldtype:'Link',options:'Company',reqd:1,default:frappe.defaults.get_user_default('Company'),onchange(){dialog?.set_value('taxes_and_charges','');}},
 {fieldname:'taxes_and_charges',label:'Modèle de taxes',fieldtype:'Link',options:'Sales Taxes and Charges Template',get_query:()=>({filters:{company:dialog?.get_value('company')||'',disabled:0}})},
 {fieldname:'customer',label:'Client',fieldtype:'Link',options:'Customer',reqd:1},{fieldname:'responsible',label:'Responsable',fieldtype:'Link',options:'User',default:frappe.session.user},
 {fieldname:'expected_start_date',label:'Début prévu',fieldtype:'Date'},{fieldname:'expected_end_date',label:'Fin de fabrication prévue',fieldtype:'Date'}
 ],async(values)=>{const result=await frappe.call({method:'frappe.client.insert',args:{doc:{doctype:'Chantier',...values}}});selected.value=result.message.name;section.value='';});}
const templateApi='mat_reco.material_reconfiguration.services.chantier_templates.';
function saveSectionTemplate(){form('Enregistrer les sections comme modèle',[
 {fieldname:'template_name',label:'Nom du modèle',fieldtype:'Data',reqd:1}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'save_template',args:{chantier:selected.value,...values}});frappe.show_alert({message:'Modèle enregistré : '+result.message,indicator:'green'});});}
function importSections(){form('Récupérer une arborescence de sections',[
 {fieldname:'source_type',label:'Source',fieldtype:'Select',options:'Modèle\nAutre chantier',default:'Modèle',reqd:1},
 {fieldname:'template',label:'Modèle',fieldtype:'Link',options:'Chantier Section Template',depends_on:'eval:doc.source_type === "Modèle"',mandatory_depends_on:'eval:doc.source_type === "Modèle"'},
 {fieldname:'source_chantier',label:'Chantier source',fieldtype:'Link',options:'Chantier',depends_on:'eval:doc.source_type === "Autre chantier"',mandatory_depends_on:'eval:doc.source_type === "Autre chantier"',get_query:()=>({filters:{name:['!=',selected.value]}})},
 {fieldtype:'HTML',fieldname:'explanation',options:'<p>Les sections et sous-sections seront ajoutées au chantier, dans leur ordre d’origine. Les sections existantes sont conservées. Aucun ouvrage ne sera copié.</p>'}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'apply_sections',args:{chantier:selected.value,...(values.source_type==='Modèle'?{template:values.template}:{source_chantier:values.source_chantier})}});section.value='';frappe.show_alert({message:result.message.count+' section(s) ajoutée(s)',indicator:'green'});});}
function generateSections(){showSectionGenerator(selected.value,async()=>{section.value='';await refresh();},describe);}
function newSection(){form('Nouvelle section',[
 {fieldname:'section_name',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'parent_chantier_section',label:'Section parente (facultatif)',fieldtype:'Link',options:'Chantier Section',default:section.value||undefined,get_query:()=>({filters:{chantier:selected.value,is_group:1}})}
 ],async(values)=>{const result=await call('create_section',{chantier:selected.value,modified:data.value.chantier.modified,...values});data.value.sections=result.sections;for(const field of ['modified','ft_active','ft_activation_key'])data.value.chantier[field]=result[field];},false);}
async function tcall(method,args={},write=true){return(await frappe.call({method:technicalApi+method,args,type:write?'POST':'GET'})).message;}
async function saveMacro(){if(busy.value||!commercialDraft.value)return false;busy.value=true;error.value='';try{await tcall('save_commercial',{chantier:selected.value,modified:data.value.chantier.modified,lines:JSON.stringify(data.value.chantier.lines),work_types:JSON.stringify(workTypes.value),upgrade_types:loose.value,commercial_extras:JSON.stringify(data.value.chantier.commercial_extras||[]),currency:data.value.chantier.currency,selling_price_list:data.value.chantier.selling_price_list,taxes_and_charges:data.value.chantier.taxes_and_charges||'',terms:data.value.chantier.terms,header:JSON.stringify(Object.fromEntries(['customer','designation','responsible','expected_start_date','expected_end_date','discount_mode','discount_value'].map(k=>[k,data.value.chantier[k]])))});await refresh();return true;}catch(e){error.value=describe(e);return false;}finally{busy.value=false;}}
function newTypeId(){return globalThis.crypto?.randomUUID?.()||'type-'+Date.now()+'-'+Math.random().toString(16).slice(2);}
function adoptTypes(){const groups=new Map();data.value.chantier.work_types=[];for(const row of data.value.chantier.lines){const key=row.designation+'|'+(row.thickness_mm||0);if(!groups.has(key)){const type={type_id:newTypeId(),designation:row.designation,thickness_mm:row.thickness_mm||0,proposed_item:row.proposed_item,common_extras:'[]'};groups.set(key,type);data.value.chantier.work_types.push(type);}row.work_type=groups.get(key).type_id;}data.value.chantier.workflow_version=2;dirty.value=true;}
function selectType(row){const type=workTypes.value.find(t=>t.type_id===row.work_type);if(type){if(!row.designation||workTypes.value.some(t=>t.designation===row.designation))row.designation=type.designation;row.thickness_mm=type.thickness_mm;if(!row.price_per_sqm_override)row.price_per_sqm=!!type.price_per_sqm;}dirty.value=true;}
function editWorkType(type=null){form(type?'Modifier le type d’ouvrage':'Nouveau type d’ouvrage',[
 {fieldname:'designation',label:'Désignation commerciale',fieldtype:'Autocomplete',ignore_validation:1,max_items:10,get_query:()=>({query:technicalApi+'designation_autocomplete'}),reqd:1,default:type?.designation||''},
 {fieldname:'thickness_mm',label:'Épaisseur (mm)',fieldtype:'Float',reqd:1,default:type?.thickness_mm||0},
 {fieldname:'pricing_unit',label:'Unité de prix par défaut',fieldtype:'Select',options:'PC\nM2',default:type?.price_per_sqm?'M2':'PC',reqd:1}
 ],async values=>{values.price_per_sqm=values.pricing_unit==='M2'?1:0;delete values.pricing_unit;if(!(Number(values.thickness_mm)>0))throw new Error('Épaisseur positive requise.');const previous=type?.designation;if(type)Object.assign(type,values);else{data.value.chantier.work_types||=[];data.value.chantier.work_types.push({...values,type_id:newTypeId(),common_extras:'[]'});typeFilter.value=data.value.chantier.work_types.at(-1).type_id;}for(const row of data.value.chantier.lines)if(row.work_type===type?.type_id){if(row.designation===previous)row.designation=values.designation;selectType(row);}dirty.value=true;},false);}
function removeWorkType(type){if(data.value.chantier.lines.some(r=>r.work_type===type.type_id)){frappe.msgprint('Réaffecter les ouvrages avant de supprimer leur type.');return;}data.value.chantier.work_types=data.value.chantier.work_types.filter(t=>t.type_id!==type.type_id);dirty.value=true;}
function commonExtras(type){return JSON.parse(type.common_extras||'[]');}
function typeExtrasTooltip(type){const extras=commonExtras(type);return extras.length?'Services / Accessoires\n'+extras.map(e=>`${e.item_code} · quantité par défaut ${fmt(e.qty||1)} · coefficient ${fmt(e.factor||1)} · prix unitaire ${fmt(e.rate)} ${data.value.chantier.currency}`).join('\n'):'Aucun service ou accessoire commun';}


function nextRepere(){const used=new Set(data.value.chantier.lines.map(l=>l.repere));let n=1;while(used.has('OUV-'+String(n).padStart(3,'0')))n++;return 'OUV-'+String(n).padStart(3,'0');}
function addDirectSale(){form('Ajouter une vente directe',[
 {fieldname:'sale_item',label:'Plaque entière, accessoire ou service',fieldtype:'Link',options:'Item',reqd:1,get_query:()=>({filters:{disabled:0,is_sales_item:1,custom_item_types:['in',['PRIMAIRE','ACCESSOIRE','SERVICE']]}})},
 {fieldname:'description',label:'Description (facultative)',fieldtype:'Data'},
 {fieldname:'qty',label:'Quantité',fieldtype:'Int',reqd:1,default:1},
 {fieldname:'rate',label:'Prix unitaire',fieldtype:'Currency',reqd:1,default:0}
 ],async values=>{if(!Number.isInteger(Number(values.qty))||Number(values.qty)<=0||Number(values.rate)<0)throw new Error('Quantité entière positive et prix positif ou nul requis.');const item=(await frappe.call({method:'frappe.client.get',args:{doctype:'Item',name:values.sale_item}})).message;data.value.chantier.lines.push({line_id:newTypeId(),repere:nextRepere(),line_kind:'Vente directe',sale_item:item.name,designation:values.description||item.item_name,qty:values.qty,rate:values.rate,rate_set:1,uom:item.stock_uom,section:section.value,length_mm:0,width_mm:0,thickness_mm:0});typeFilter.value='';dirty.value=true;},false);}
function editMacro(row=null){
 if(loose.value&&!row&&(!typeFilter.value||typeFilter.value==='__direct__')){addDirectSale();return;}
 if(loose.value&&row?.line_kind!=='Vente directe'&&!workTypes.value.some(t=>t.type_id===(row?.work_type||typeFilter.value))){frappe.msgprint('Créer un type d’ouvrage avant d’ajouter les ouvrages.');return;}
 const line={...(row||{}),repere:nextRepere(),line_id:globalThis.crypto?.randomUUID?.()||'line-'+Date.now()+'-'+Math.random().toString(16).slice(2),designation:row?.designation||'',section:row?.section||section.value,qty:row?.qty||1,uom:row?.uom||'PC',rate:row?.rate||0,rate_set:row?.rate_set||0};
 if(loose.value&&row?.line_kind!=='Vente directe'){const t=workTypes.value.find(t=>t.type_id===row?.work_type)||workTypes.value.find(t=>t.type_id===typeFilter.value)||workTypes.value[0];line.work_type=t.type_id;line.designation=row?.designation||t.designation;line.thickness_mm=t.thickness_mm;if(!row?.price_per_sqm_override)line.price_per_sqm=!!t.price_per_sqm;}
 delete line.name;data.value.chantier.lines.push(line);inheritDraftExtras();dirty.value=true;
}
function preventLeave(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
window.addEventListener('beforeunload',preventLeave);
onBeforeUnmount(()=>window.removeEventListener('beforeunload',preventLeave));
const extrasFor=(id)=>(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id===id);
function removeExtra(extra){if(extra.inherited_from)return;frappe.confirm('Retirer ce service ou accessoire ?',()=>{data.value.chantier.commercial_extras=data.value.chantier.commercial_extras.filter(e=>e.line_id!==extra.line_id);dirty.value=true;});}
function removeMacro(row){frappe.confirm('Retirer cet ouvrage du brouillon commercial ?',()=>{assignmentTargets.value=assignmentTargets.value.filter(id=>id!==row.line_id);drawerTargets.value=drawerTargets.value.filter(id=>id!==row.line_id);data.value.chantier.lines=data.value.chantier.lines.filter(l=>l.line_id!==row.line_id);data.value.chantier.commercial_extras=(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id!==row.line_id);dirty.value=true;});}
async function technical(){if(!ftActive.value||dirty.value){frappe.msgprint('Enregistrer le chantier puis activer FT avant de préparer la fiche technique.');return;}busy.value=true;error.value='';try{const name=(await frappe.call({method:'mat_reco.material_reconfiguration.services.task_notifications.handoff_study',args:{chantier:selected.value,request_key:globalThis.crypto?.randomUUID?.()||String(Date.now())}})).message;frappe.set_route('technical-study',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function viewTechnical(){if(data.value.technical)frappe.set_route('technical-study',data.value.technical.name);}
async function toggleFT(){if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{await frappe.call({method:'mat_reco.material_reconfiguration.services.ft_activation.set_ft_active',args:{chantier:selected.value,active:data.value.chantier.ft_active?0:1,modified:data.value.chantier.modified}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function submitCommercial(){frappe.confirm(loose.value?'Valider les quantités, prix et conditions commerciales du chantier ?':'Valider les quantités, prix et conditions commerciales après la fiche technique ?',async()=>{if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{await frappe.call({method:'frappe.client.submit',args:{doc:data.value.chantier}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
async function copyChantier(action='duplicate'){
 if(needsSaveBeforeCopy({dirty:dirty.value,docstatus:data.value.chantier?.docstatus,editable:commercialDraft.value})&&!(await saveMacro()))return;
 const proceed=async()=>{
  busy.value=true;error.value='';try{
   const name=await tcall('copy_dossier',{chantier:selected.value,modified:data.value.chantier.modified,action});
   selected.value=name;section.value='';typeFilter.value='';sectionTarget.value='';assignmentTargets.value=[];closeExtras();
   await frappe.set_route('chantiers',name);await refresh();
  }catch(e){error.value=describe(e);}finally{busy.value=false;}
 };
 if(action==='cancel_and_amend')frappe.confirm('Annuler ce chantier et créer son amendement ? Cette action est interdite s’il a déjà participé à un devis, une commande ou un MCP.',proceed);
 else await proceed();
}
function cancelChantier(){if(data.value.chantier?.docstatus===1&&data.value.permissions?.amend&&data.value.permissions?.chantier){copyChantier('cancel_and_amend');return;}frappe.confirm(loose.value?'Annuler le chantier commercial ? Cette action est interdite s’il a déjà participé à un devis, une commande ou un MCP.':'Annuler ce chantier ? Toutes les fiches techniques et tous les devis doivent être supprimés ou annulés.',async()=>{busy.value=true;error.value='';try{await tcall('cancel_dossier',{chantier:selected.value,modified:data.value.chantier.modified});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
async function newQuotation(){const selection=Object.entries(chosen.value).filter(([id,v])=>v.selected&&v.qty>0).map(([line_id,v])=>({line_id,qty:v.qty}));if(!selection.length){frappe.msgprint('Sélectionner au moins un ouvrage et sa quantité.');return;}const dialog=new frappe.ui.Dialog({title:'Générer le devis depuis le chantier approuvé',fields:[{fieldname:'submit',label:'Valider également le devis',fieldtype:'Check',default:1}],primary_action_label:'Générer',async primary_action(v){dialog.disable_primary_action();busy.value=true;error.value='';try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('generate_quotation',{chantier:selected.value,selections:JSON.stringify(selection),request_key:quoteKey.value,submit:v.submit});quoteKey.value=null;dialog.hide();await refresh();open('Quotation',name);}catch(e){error.value=describe(e);}finally{dialog.enable_primary_action();busy.value=false;}}});dialog.show();}
function confirmOrder(quote){const dialog=new frappe.ui.Dialog({title:'Confirmer l’acceptation client',fields:[{fieldname:'order_type',label:'Type de commande',fieldtype:'Select',options:(frappe.session?.user==='Administrator'||frappe.user?.has_role?.('UG COMMANDES B'))?'A\nB':'A',default:'A',reqd:1},{fieldname:'acceptance',label:'Référence ou justificatif de l’accord client',fieldtype:'Data',reqd:1},{fieldname:'direct_only',label:'Commander uniquement les ventes directes',fieldtype:'Check',default:0},{fieldname:'delivery_date',label:'Date prévue',fieldtype:'Date',reqd:1,default:frappe.datetime.add_days(frappe.datetime.get_today(),7)}],primary_action_label:'Créer et valider la commande',async primary_action(v){dialog.disable_primary_action();try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('confirm_order',{quotation:quote.name,acceptance_reference:v.acceptance,delivery_date:v.delivery_date,request_key:quoteKey.value,direct_only:v.direct_only,order_type:v.order_type});quoteKey.value=null;dialog.hide();open('Sales Order',name);}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
async function mpp(line){busy.value=true;error.value='';try{const name=await call('create_mpp',{sales_order:line.sales_order,sales_order_item:line.sales_order_item});open('Material Production Plan',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function workshop(){sessionStorage.setItem('univers-workshop-chantier',selected.value);frappe.set_route('workshop-cockpit');}
function onOrderUpdate(event){if(event?.doctype==='Sales Order'&&!busy.value&&!dirty.value)refresh();}
function show(){pageActive.value=true;frappe.realtime?.off('workshop_updated',onOrderUpdate);frappe.realtime?.on('workshop_updated',onOrderUpdate);document.body.classList.remove('ug-chantier-active');const stored=frappe.get_route()[1]||sessionStorage.getItem("univers-chantier-selected");if(stored){selected.value=stored;section.value="";sessionStorage.removeItem("univers-chantier-selected");}refresh();clearInterval(timer);timer=setInterval(()=>{if(!busy.value&&!dirty.value)refresh();},60000);}
function hide(){pageActive.value=false;frappe.realtime?.off('workshop_updated',onOrderUpdate);document.body.classList.remove('ug-chantier-active');serial++;clearInterval(timer);timer=null;}
onBeforeUnmount(hide);defineExpose({show,hide});
</script>

<template>
<div class="ug-chantiers" :class="{'drawer-open':commercialDraft&&(drawerTargets.length||drawerWorkType)}">
 <div class="chantier-content">
 <div v-if="stale" class="stale-notice" role="status">Ce chantier a été modifié depuis son chargement. Vos saisies sont conservées jusqu’à l’actualisation. <button :disabled="busy" @click="reloadDossier">Actualiser</button></div>
 <header><div><p>UNIVERS GLASS › Chantier › {{selected}}</p><h1>Chantier <small>{{data.chantier?.docstatus===0?'Brouillon commercial':stateName(data.chantier?.status)}}</small></h1></div><div class="actions"><ChantierPresence :name="data.chantier?.name" :active="pageActive" @updated="onDocumentUpdate" /><button :disabled="busy" title="Recharger le chantier depuis le serveur" @click="reloadDossier">↻ Actualiser</button><button :disabled="busy||!data.permissions?.chantier" @click="newChantier">+ Nouveau</button><button v-if="commercialDraft" :disabled="busy||!dirty" @click="frappe.confirm('Abandonner les modifications ?',refresh)">Annuler</button><button v-if="commercialDraft" class="primary" :disabled="busy||!dirty" @click="saveMacro">{{busy?'Enregistrement…':'▣ Enregistrer'}}</button><button v-if="!loose&&selected&&data.permissions?.write&&data.chantier?.docstatus!==2" :class="{primary:ftActive}" :aria-pressed="ftActive" :disabled="busy||data.permissions?.ft_locked" :title="data.permissions?.ft_locked?'Supprimer la fiche technique pour modifier le chantier':'Activer ou désactiver la préparation technique'" @click="toggleFT">{{ftActive?'✓ Activer FT':'Activer FT'}}</button><details><summary aria-label="Autres actions">•••</summary><div class="more-actions">
 <button v-if="commercialDraft" :disabled="dirty||busy" @click="frappe.new_doc('Data Import',{reference_doctype:'Chantier',import_type:'Update Existing Records'})">Importer Excel</button><button v-if="selected" @click="open('Chantier',selected)">Ouvrir le dossier Frappe</button><button :disabled="dirty||!selected" @click="printDocument('Chantier',selected)">Imprimer A4</button><button v-if="data.technical" @click="viewTechnical">Fiche technique</button><button v-if="!loose&&data.chantier?.docstatus!==2&&!data.technical" :disabled="busy||!data.permissions?.technical||!ftActive" @click="technical">Préparer la fiche technique</button><button v-if="commercialOpen&&data.permissions?.submit" :disabled="busy||dirty||(!loose&&(data.technical?.docstatus!==1||data.technical_stale))" @click="submitCommercial">Valider le commercial</button><button :disabled="busy||!data.permissions?.quotation||!readyForQuote" @click="newQuotation">Générer un devis</button><button v-if="selected&&data.permissions?.chantier" :disabled="busy" @click="copyChantier()">Dupliquer le chantier</button><button v-if="selected&&data.permissions?.cancel&&data.chantier?.docstatus!==2&&data.chantier?.status!=='Cancelled'" :disabled="busy||dirty||!!data.chantier?.downstream_started" :title="data.chantier?.downstream_started?'Annulation interdite : chantier déjà utilisé dans un devis, une commande ou un MCP':''" @click="cancelChantier">{{data.chantier?.docstatus===1&&data.permissions?.amend&&data.permissions?.chantier?'Annuler puis amender':'Annuler le chantier'}}</button><button v-if="selected&&data.permissions?.amend&&data.permissions?.chantier&&data.chantier?.docstatus===2" :disabled="busy" @click="copyChantier('amend')">Amender le chantier</button><button @click="workshop">Atelier</button><button v-for="q in data.quotations" :key="q.name" @click="open('Quotation',q.name)">{{q.name}} · {{q.status}}</button><button v-for="q in data.quotations.filter(q=>q.docstatus===1)" :key="q.name+'order'" @click="confirmOrder(q)">Commander {{q.name}}</button>
 </div></details></div></header>
 <button v-if="commercialDraft&&!loose&&!data.technical&&!data.quotations?.length&&!data.sales_orders?.length" @click="adoptTypes">Adopter les types d’ouvrage et les parcours indépendants</button>
 <ChantierAutocomplete v-model="selected" :items="data.chantiers" :disabled="busy||dirty" @change="choose" />
 <div v-if="error" class="alert" role="alert">{{error}}</div>
 <p v-if="dirty" role="status">Modifications non enregistrées</p>
 <p v-if="data.permissions?.ft_locked" role="status">Chantier verrouillé : supprimer la fiche technique avant de modifier le chantier.</p>
 <template v-if="data.chantier?.name===selected">
 <div class="header-fields" @change="markDirty()">
 <section><label>Client <FrappeCell v-model="data.chantier.customer" doctype="Customer" :disabled="!commercialDraft||busy" /></label><label>Nom du chantier <input v-model="data.chantier.designation" :disabled="!commercialDraft||busy" @input="markDirty()" /></label><label>Responsable <FrappeCell v-model="data.chantier.responsible" doctype="User" :disabled="!commercialDraft||busy" /></label><label>Remise<select v-model="data.chantier.discount_mode" :disabled="!commercialDraft||busy" aria-label="Type de remise" @change="markDirty()"><option>Pourcentage</option><option>Montant</option></select></label><label>{{data.chantier.discount_mode==='Montant'?'Remise globale ('+data.chantier.currency+')':'Remise par défaut (%)'}}<input v-model.number="data.chantier.discount_value" type="number" min="0" :max="data.chantier.discount_mode==='Montant'?undefined:100" step="any" :disabled="!commercialDraft||busy" aria-label="Valeur de remise" @input="markDirty()" /></label></section>
 <section><label>Devise <FrappeCell v-model="data.chantier.currency" doctype="Currency" :disabled="!commercialDraft||busy" /></label><label>Liste de prix <FrappeCell v-model="data.chantier.selling_price_list" doctype="Price List" :disabled="!commercialDraft||busy" /></label><label>Modèle de taxes <FrappeCell v-model="data.chantier.taxes_and_charges" doctype="Sales Taxes and Charges Template" label="Modèle de taxes" :filters="{company:data.chantier.company,disabled:0}" :disabled="!commercialDraft||busy" /></label><label>Début prévu <input type="date" v-model="data.chantier.expected_start_date" :disabled="!commercialDraft||busy" /></label><label>Fin de fabrication prévue <input type="date" v-model="data.chantier.expected_end_date" :disabled="!commercialDraft||busy" /></label><label>Statut <span>{{stateName(data.chantier.status)}}</span></label></section>
 </div>
 <nav v-if="data.sales_orders?.length" class="linked-orders" aria-label="Commandes du chantier"><span>Commandes</span><button v-for="order in data.sales_orders" :key="order.name" type="button" @click="open('Sales Order',order.name)">{{order.name}} · {{order.docstatus===0?'Brouillon':order.docstatus===2?'Annulée':stateName(order.status)}} · {{fmt(order.grand_total)}} {{order.currency}}</button></nav>
 <section v-if="loose" class="work-types-panel">
 <div class="work-types-toolbar"><button :class="{active:!typeFilter}" :aria-pressed="!typeFilter" @click="typeFilter=''">Tous</button>
 <div class="work-types-list" aria-label="Types d’ouvrage disponibles"><article v-for="type in workTypes" :key="type.type_id" class="work-type-card" :class="{active:typeFilter===type.type_id}">
 <button class="type-filter" :class="{active:typeFilter===type.type_id}" :aria-pressed="typeFilter===type.type_id" :title="typeExtrasTooltip(type)" @click="typeFilter=type.type_id">{{type.designation}} — {{type.thickness_mm}} mm <small :title="'Nombre d’ouvrages liés'">{{data.chantier.lines.filter(r=>r.work_type===type.type_id).length}}</small><small v-if="type.price_per_sqm">/ m²</small></button>
 <template v-if="commercialDraft"><button class="type-icon" :disabled="busy" :aria-label="'Modifier '+type.designation" title="Modifier le type d’ouvrage" @click="editWorkType(type)"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 3 5 5-12 12-6 1 1-6L16 3Z M13 6l5 5" /></svg></button><button class="type-icon" :disabled="busy" :aria-label="'Services et accessoires du type '+type.designation" :title="typeExtrasTooltip(type)" @click="openTypeExtras(type)"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 4h8v4h4v8h-4v4H8v-4H4V8h4z" /></svg></button><button class="type-icon type-delete" :disabled="busy" :aria-label="'Supprimer '+type.designation" title="Supprimer le type d’ouvrage" @click="removeWorkType(type)"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7" /></svg></button></template>
 </article></div><button v-if="commercialDraft" :disabled="busy" @click="editWorkType()">+ Type</button></div>

 </section>
 <div class="body" :class="{'sections-closed':!sectionsOpen}">
 <aside class="sections"><div class="heading"><h2 v-if="sectionsOpen">Sections</h2><button :aria-expanded="sectionsOpen" aria-label="Replier ou ouvrir les sections" @click="sectionsOpen=!sectionsOpen">{{sectionsOpen?'«':'»'}}</button></div><template v-if="sectionsOpen"><template v-if="sectionRow&&commercialDraft"><div class="section-picker-heading"><span>Section de {{sectionRow.repere}}</span><button type="button" aria-label="Terminer le choix de section" @click="sectionTarget=''">×</button></div><label class="section-option" :class="{active:!sectionRow.section}"><span>Sans section</span><input type="checkbox" aria-label="Sans section pour la ligne en cours" :checked="!sectionRow.section" :disabled="busy" @change="assignSection('')" /></label><label v-for="s in data.sections" :key="s.name" class="section-option" :class="{active:sectionRow.section===s.name}" :style="{paddingLeft:(8+depth(s)*12)+'px'}"><span>{{s.section_name}}</span><input type="checkbox" :aria-label="'Affecter '+s.section_name+' à la ligne en cours'" :checked="sectionRow.section===s.name" :disabled="busy" @change="assignSection($event.target.checked?s.name:'')" /></label></template><template v-else><button :class="{active:!section}" @click="section=''">Tout le chantier <small>{{data.chantier.lines.length}}</small></button><button v-for="s in data.sections" :key="s.name" :class="{active:section===s.name}" :style="{paddingLeft:(8+depth(s)*12)+'px'}" @click="section=s.name">{{s.section_name}} <small>{{data.chantier.lines.filter(l=>l.section===s.name).length}}</small></button></template><template v-if="commercialDraft&&data.permissions?.section"><button :disabled="busy" @click="newSection">+ Section</button><details><summary>Gestion des sections</summary><button :disabled="busy||dirty" @click="importSections">Récupérer</button><button :disabled="busy||dirty" @click="generateSections">Générer avec le LLM</button><button v-if="data.permissions?.section_template" :disabled="busy||dirty" @click="saveSectionTemplate">Enregistrer comme modèle</button><button v-if="section" @click="open('Chantier Section',section)">Modifier la section</button></details></template></template></aside>
 <main class="panel macro" aria-label="Ouvrages"><div v-if="data.technical_stale" class="alert">La fiche technique décrit une autre version des types. Le parcours commercial reste indépendant.</div>
 <div class="table" @keydown.enter.prevent @input="dirty=commercialDraft||dirty" @change="dirty=commercialDraft||dirty"><table><thead><tr><th><input v-if="commercialDraft" type="checkbox" aria-label="Sélectionner les ouvrages visibles" :checked="!!macroLines.length&&macroLines.every(l=>assignmentTargets.includes(l.line_id))" @input.stop @change.stop="toggleAllTargets" /></th><th></th><th>Article</th><th>Dimensions techniques / proposées (mm)</th><th>Qté</th><th>Unité</th><th>Prix unitaire</th><th>Remise (%)</th><th>Montant</th><th>Actions</th></tr></thead><tbody><template v-for="row in macroLines" :key="row.line_id"><tr :class="{'assignment-selected':assignmentTargets.includes(row.line_id)}"><td><input v-if="commercialDraft" v-model="assignmentTargets" type="checkbox" :value="row.line_id" :disabled="busy" :aria-label="'Sélectionner '+row.repere" @change.stop @input.stop /><template v-else-if="chosen[row.line_id]"><input v-model="chosen[row.line_id].selected" type="checkbox" :disabled="!readyForQuote" /><input v-if="readyForQuote" v-model.number="chosen[row.line_id].qty" type="number" :max="row.qty-(data.quote_usage?.[row.line_id]||0)" min="0" class="qty-input" /></template></td>
 <td><button class="article-toggle" :aria-expanded="!!expandedArticles[row.line_id]" :aria-label="'Prestations de '+row.repere" @click="expandedArticles[row.line_id]=!expandedArticles[row.line_id]">{{expandedArticles[row.line_id]?'▾':'▸'}}</button></td>
 <td><FrappeCell v-if="loose" v-model="row.designation" autocomplete label="Description de l’ouvrage" :disabled="!commercialDraft||busy" @update:model-value="markDirty()" /><FrappeCell v-else v-model="row.designation" autocomplete label="Désignation" :disabled="!commercialDraft||busy" @update:model-value="markDirty()" /><small>{{row.repere}}</small></td>
 <td class="dimensions"><span v-if="row.line_kind==='Vente directe'">Vente directe · {{row.sale_item}}</span><template v-else><template v-for="(field,i) in ['length_mm','width_mm','thickness_mm']" :key="field"><span v-if="i"> × </span><input v-model.number="row[field]" type="number" min="0" step="any" :aria-label="field" :disabled="!commercialDraft||busy||(loose&&field==='thickness_mm')" /></template></template><small v-if="!loose&&techLine(row.line_id)">Technique : {{techLine(row.line_id).length_mm}} × {{techLine(row.line_id).width_mm}} × {{techLine(row.line_id).thickness_mm}}</small></td>
 <td><input v-model.number="row.qty" type="number" min="1" step="1" aria-label="Quantité" :disabled="!commercialDraft||busy" class="qty-input" /></td><td><select v-if="row.line_kind!=='Vente directe'" :value="row.price_per_sqm?'M2':'PC'" :disabled="!commercialDraft||busy" :aria-label="'Unité de prix de '+row.repere" @change="row.price_per_sqm=$event.target.value==='M2';row.price_per_sqm_override=1;markDirty()"><option>PC</option><option>M2</option></select><FrappeCell v-else v-model="row.uom" doctype="UOM" disabled /></td>
 <td><input v-model.number="row.rate" type="number" min="0" step="any" aria-label="Prix unitaire" :disabled="!commercialDraft||busy" /><small v-if="row.price_per_sqm">Prix / m²</small></td><td><input v-model.number="row.discount_percentage" type="number" min="0" max="100" step="any" :disabled="!commercialDraft||busy||data.chantier.discount_mode==='Montant'" :aria-label="'Remise de '+row.repere" @input="setLineDiscount(row)" /></td><td>{{fmt(lineAmount(row))}}</td>
 <td><div class="row-actions" v-if="commercialDraft"><button :disabled="busy" title="Dupliquer" aria-label="Dupliquer l’ouvrage" @click="editMacro(row)">⧉</button><button :disabled="busy" title="Supprimer" aria-label="Supprimer l’ouvrage" @click="removeMacro(row)" class="delete-ouvrage"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7" /></svg></button><button :disabled="busy" title="Affecter une section" aria-label="Affecter une section" :aria-pressed="sectionTarget===row.line_id" @click="pickSection(row)"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 7V4h6l3 3h9v13H3z" /></svg></button><button :disabled="busy" title="Services / Accessoires" aria-label="Affecter des services et accessoires" @click="openExtras(row)"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M8 4h8v4h4v8h-4v4H8v-4H4V8h4z" /></svg></button></div></td></tr>
 <tr v-if="expandedArticles[row.line_id]" class="ouvrage-extras"><td></td><td colspan="9"><p class="ouvrage-section"><strong>Section :</strong> {{sectionName(row.section)}}</p><p v-if="!extrasFor(row.line_id).length">Aucune prestation affectée.</p><div v-for="extra in extrasFor(row.line_id)" :key="extra.line_id" class="extra-line"><span>{{extra.item_name||extra.item_code}} · {{extra.item_type}} <small v-if="extra.inherited_from">Hérité du type d’ouvrage</small></span><span>{{fmt(extra.qty)}} {{extra.uom}} × {{fmt(extra.rate)}} = {{fmt(lineAmount(extra))}}</span><label v-if="data.chantier.discount_mode!=='Montant'">Remise (%) <input v-model.number="extra.discount_percentage" type="number" min="0" max="100" step="any" :disabled="!commercialDraft||busy" :aria-label="'Remise de '+extra.item_code+' pour '+row.repere" @input="setLineDiscount(extra)" /></label><button v-if="commercialDraft&&!extra.inherited_from" @click="removeExtra(extra)">Retirer</button></div></td></tr>
 </template></tbody></table></div>
 <footer><button v-if="commercialDraft" :disabled="busy" @click="editMacro()">+ Ajouter une ligne</button><strong>Total HT après remise : {{fmt(total)}} {{data.chantier.currency}}</strong></footer><details class="terms"><summary>Conditions commerciales</summary><textarea v-model="data.chantier.terms" :disabled="!commercialDraft||busy" @input="markDirty()"></textarea></details>
 </main>

 </div></template><div v-else class="empty">Sélectionnez un chantier ou créez un nouveau dossier.</div>
 </div>
 <CommercialExtrasPanel v-if="commercialDraft&&(drawerTargets.length||drawerWorkType)" :key="selected+':'+drawerTypeId" :chantier="data.chantier" :work-type="drawerWorkType" :parent-line-ids="drawerTargets" :disabled="busy" :before-apply="beforeBatch" @close="closeExtras" @applied="applyExtras" @type-applied="applyTypeExtras" @updated="updateLineExtra" />
</div>
</template>
